package com.wansheng.visitor.auth;import java.util.*;import javax.sql.DataSource;import org.flywaydb.core.Flyway;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;
@Component class BootstrapAccounts implements CommandLineRunner{private final AccountRepository r;private final PasswordEncoder e;private final Map<String,String>p;private final DataSource dataSource;BootstrapAccounts(AccountRepository r,PasswordEncoder e,DataSource dataSource,@Value("${visitor.bootstrap.password}")String sp,@Value("${visitor.security.guard-password}")String gp,@Value("${visitor.security.dorm-password}")String dp,@Value("${visitor.security.admin-password}")String ap){this.r=r;this.e=e;this.dataSource=dataSource;p=Map.of("system-admin",sp,"guard",gp,"dorm",dp,"admin",ap);}@Override public void run(String...a){Flyway.configure().dataSource(dataSource).schemas("auth_schema").defaultSchema("auth_schema").createSchemas(true).load().migrate();seed("system-admin","系统管理员","SYSTEM_ADMIN");seed("guard","门卫","GUARD");seed("dorm","宿舍管理员","DORM_ADMIN");seed("admin","后台管理员","ADMIN");}private void seed(String u,String n,String role){if(r.find(u).isEmpty())r.create(u,n,e.encode(p.get(u)),role);}}
